package org.lbl.intranet.lineage.controller;
import jakarta.validation.Valid;
import org.lbl.common.result.Result;
import org.lbl.intranet.lineage.request.TransactionFieldSourceRequest;
import org.lbl.intranet.lineage.service.LineageService;
import org.lbl.intranet.lineage.vo.*;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.web.bind.annotation.*;
import java.util.List;
@RestController @RequestMapping("/api/intranet/lineage") public class LineageController { private final LineageService service; public LineageController(LineageService service){this.service=service;} @GetMapping("/source-options") @PreAuthorize("hasAuthority('intranet:transaction:list')") Result<List<LineageOptionVO>> options(){return Result.ok(service.options());} @GetMapping("/transaction-fields/{fieldId}") @PreAuthorize("hasAuthority('intranet:transaction:list')") Result<TransactionFieldSourceVO> get(@PathVariable Long fieldId){return Result.ok(service.get(fieldId));} @PutMapping("/transaction-fields/{fieldId}") @PreAuthorize("hasAuthority('intranet:transaction:update')") Result<TransactionFieldSourceVO> save(@PathVariable Long fieldId,@Valid @RequestBody TransactionFieldSourceRequest r){return Result.ok(service.save(fieldId,r));} @GetMapping("/impact") @PreAuthorize("hasAuthority('intranet:transaction:list')") Result<List<ImpactItemVO>> impact(@RequestParam String sourceType,@RequestParam Long sourceFieldId){return Result.ok(service.impact(sourceType,sourceFieldId));} @GetMapping("/impact-graph") @PreAuthorize("hasAuthority('intranet:transaction:list')") Result<LineageGraphVO> graph(@RequestParam String sourceType,@RequestParam Long sourceFieldId){return Result.ok(service.graph(sourceType,sourceFieldId));} @GetMapping("/search-options") @PreAuthorize("hasAuthority('intranet:transaction:list')") Result<List<LineageSearchOptionVO>> search(@RequestParam String entryType,@RequestParam String keyword){return Result.ok(service.search(entryType,keyword));} @GetMapping("/graph") @PreAuthorize("hasAuthority('intranet:transaction:list')") Result<LineageGraphVO> graphByEntry(@RequestParam String entryType,@RequestParam Long entryId){return Result.ok(service.graphByEntry(entryType,entryId));} }
